print(f"library panels rebuilt: {len(lib_panels)} | {time.time()-t0:.1f}s", flush=True)

fwd_raw = {h: forward_returns(prices, h) for h in (1, 2, 3, 5, 10, 20)}
fwd_rank = {h: rank_matrix(fwd_raw[h].reindex(grid)) for h in fwd_raw}

all_dates = sorted(set().union(*[set(d.index) for d in prices.values()]))
grid2 = pd.DatetimeIndex([d for d in all_dates if d > VAL_END])
fwd2_rank = rank_matrix(forward_returns(prices, 10).reindex(grid2))
print(f"online grid: {len(grid2)} dates {grid2.min().date()}..{grid2.max().date()}", flush=True)

# ---------------- candidate factors (designed orthogonal) ----------------
def f_seasonality_month_24(df, s):
    c = df['close']
    fwd = c.shift(-10) / c - 1.0
    out = pd.Series(np.nan, index=c.index)
    for m in range(1, 13):
        sub = fwd[fwd.index.month == m]
        roll = sub.rolling('730D', min_periods=4).mean().shift(1)
        out.loc[roll.index] = roll
    return out

def f_ret_skew_60(df, s):
    return df['close'].pct_change().rolling(60).skew()

def f_ret_skew_20(df, s):
    return df['close'].pct_change().rolling(20).skew()

def f_ret_kurt_20(df, s):
    return df['close'].pct_change().rolling(20).kurt()

def f_down_vol_ratio_20(df, s):
    r = df['close'].pct_change()
    total = r.rolling(20).std()
    dn = r.clip(upper=0)
    dvol = np.sqrt((dn ** 2).rolling(20).mean())
    return dvol / total.replace(0, np.nan)

def f_var_ratio_5_20(df, s):
    r = df['close'].pct_change()
    s5 = r.rolling(5).sum()
    vr = s5.rolling(80).var() / (5.0 * r.rolling(80).var().replace(0, np.nan))
    return vr

def f_max_gain_asym_20(df, s):
    r = df['close'].pct_change()
    up = r.rolling(20).max()
    dn = r.rolling(20).min().abs()
    return up / dn.replace(0, np.nan)

def f_efficiency_ratio_10(df, s):
    c = df['close']
    num = (c - c.shift(10)).abs()
    den = c.diff().abs().rolling(10).sum()
    return num / den.replace(0, np.nan)

def f_vol_cv_20(df, s):
    r = df['close'].pct_change()
    mu = r.rolling(20).mean(); sd = r.rolling(20).std()
    return sd / mu.abs().replace(0, np.nan)

def f_high_low_pos_10(df, s):
    hi = df['high'].rolling(10).max(); lo = df['low'].rolling(10).min()
    return (df['close'] - lo) / (hi - lo).replace(0, np.nan)

def f_vol_skew_20(df, s):
    r = df['close'].pct_change()
    v20 = r.rolling(20).std()
    return v20.rolling(120).skew()

cands = {
    'seasonality_month_24': (f_seasonality_month_24, 'trailing 2y avg fwd10 ret for same calendar month', 'calendar seasonality'),
    'ret_skew_60':           (f_ret_skew_60, 'skewness of 60d daily returns', 'return asymmetry (medium)'),
    'ret_skew_20':           (f_ret_skew_20, 'skewness of 20d daily returns', 'return asymmetry (short)'),
    'ret_kurt_20':           (f_ret_kurt_20, 'kurtosis of 20d daily returns', 'tail thickness'),
    'down_vol_ratio_20':     (f_down_vol_ratio_20, 'downside semidev / total vol (20d)', 'own downside participation'),
    'var_ratio_5_20':        (f_var_ratio_5_20, 'Var(5d sum)/(5*Var(1d)) est over 80d', 'trend vs mean-reversion (VR5)'),
    'max_gain_asym_20':      (f_max_gain_asym_20, 'max up-day / |max down-day| (20d)', 'tail gain asymmetry'),
    'efficiency_ratio_10':   (f_efficiency_ratio_10, '|10d move| / sum(|1d moves|,10)', 'trend efficiency'),
    'vol_cv_20':             (f_vol_cv_20, 'std20 / |mean20|', 'volatility coefficient of variation'),
    'high_low_pos_10':       (f_high_low_pos_10, '(close - low10)/(high10-low10)', 'short-term range position'),
    'vol_skew_20':           (f_vol_skew_20, 'skew of 20d realized vol over 120d', 'vol-regime tail asymmetry'),
}

def max_lib_corr(panel):
    pr = rank_matrix(pd.DataFrame(signal_matrix(panel, grid), index=grid, columns=WATCHLIST))
    best, best_id, per_id = 0.0, None, {}
    for fid, lr in lib_rank.items():
        r = spearman_from_ranks(pr, lr)
        rr = r[np.isfinite(r)]
        if len(rr) > 0:
            per_id[fid] = float(np.nanmean(rr))
            if abs(per_id[fid]) > best:
                best, best_id = abs(per_id[fid]), fid
    return best, best_id, per_id

def fast_validate(panel):
