    if np.isfinite(ic10).sum() < 100:
        return None
    ic_mean = float(np.nanmean(ic10)); ic_std = float(np.nanstd(ic10, ddof=1))
    icir = ic_mean / ic_std if ic_std > 0 else 0.0
    hit = float((ic10 > 0).mean()) if ic_mean >= 0 else float((ic10 < 0).mean())
    fac = panel[(panel.index >= VAL_START) & (panel.index <= VAL_END)]
    total = fac.shape[0] * fac.shape[1]
    coverage = float(fac.notna().sum().sum()) / total if total else 0.0
    ge8 = float((fac.notna().sum(axis=1) >= 8).mean())
    turn = float(fac.rank(axis=1).diff(10).abs().mean().mean()) if len(fac) > 10 else float('nan')
    decay = {str(h): float(np.nanmean(spearman_from_ranks(pr, fwd_rank[h])[val_mask])) for h in (1, 2, 3, 5, 10, 20)}
    m = {'ic': ic_mean, 'icir': icir, 'ic_hit_ratio': hit, 'n_ic_dates': int(np.isfinite(ic10).sum()),
         'coverage_asset_days': coverage, 'coverage_dates_ge8': ge8, 'turnover_10d_rank': turn,
         'decay_ic_by_horizon': decay}
    gv = grid[val_mask]
    for nm, a, b in [('ic_2020_2022', '2020-01-01', '2022-12-31'),
                     ('ic_2023_2024', '2023-01-01', '2024-12-31'),
                     ('ic_2025_2026', '2025-01-01', '2026-07-15')]:
        sub = ic10[(gv >= pd.Timestamp(a)) & (gv <= pd.Timestamp(b))]
        m[nm] = float(np.nanmean(sub)) if np.isfinite(sub).sum() > 30 else float('nan')
    pr2 = rank_matrix(pd.DataFrame(panel.reindex(grid2), index=grid2, columns=WATCHLIST))
    ic2 = spearman_from_ranks(pr2, fwd2_rank); ic2 = ic2[np.isfinite(ic2)]
