        m['online_icir'] = float(np.nanmean(ic2) / sd) if sd > 0 else 0.0; m['online_n'] = int(len(ic2))
    return m

results = {}
for fid, (fn, desc, tag) in cands.items():
    t1 = time.time()
    try:
        panel = factor_to_panel(fn, prices)
        if panel is None or len(panel) == 0:
            print(f"{fid}: EMPTY -> skip", flush=True); continue
