    for wname, ws, we in WINDOWS:
        st = ic_stats(aligned, ws, we)
        if st is None:
            row.append(f"{'n<60':>26}")
        else:
            gate = 'PASS' if (abs(st['ic']) >= 0.007 and abs(st['icir']) >= 0.084) else 'fail'
            row.append(f"ic={st['ic']:+.4f} ir={st['icir']:+.3f} {gate:<4} n={st['n']}")
        r_[wname] = st
    out[fid] = r_
    print(" | ".join(row))

